-- Vasfiy Market: boshlang'ich katalog (12 mahsulot, 4 til). Idempotent — qayta Run xavfsiz.
insert into public.settings(key, value) select 'extraCats', '{}'::jsonb where not exists (select 1 from public.settings where key='extraCats');
update public.settings set value = jsonb_set(coalesce(value,'{}'::jsonb), '{product}', coalesce(value->'product','{}'::jsonb) || '{"parfum": {"en": "Perfumes", "uz": "Parfyumeriya", "icon": "🌸"}, "charm": {"en": "Leather goods", "uz": "Charm buyumlar", "icon": "🧳"}, "kiyim": {"en": "Clothing", "uz": "Kiyim", "icon": "🧥"}, "poyabzal": {"en": "Shoes", "uz": "Poyabzal", "icon": "👞"}, "aksessuar": {"en": "Accessories", "uz": "Aksessuarlar", "icon": "⌚"}}'::jsonb) where key='extraCats';

