select 'product', '{"title": "Dior Sauvage EDP 100 ml", "titleUz": "Dior Sauvage parfyum suvi 100 ml", "titleRu": "Dior Sauvage парфюмерная вода 100 мл", "titleDe": "Dior Sauvage EDP 100 ml", "desc": "Original, sealed, EAN-coded — sourced from an authorized EU distributor. Delivery to Uzbekistan 7–14 days (pre-order).", "descUz": "Original, muhrlangan, EAN kodli — Yevropaning rasmiy distribyutoridan. O''zbekistonga yetkazish 7–14 kun (oldindan buyurtma).", "descRu": "Оригинал, запечатан, с EAN-кодом — от официального дистрибьютора ЕС. Доставка в Узбекистан 7–14 дней (предзаказ).", "descDe": "Original, versiegelt, mit EAN-Code — vom autorisierten EU-Händler. Lieferung nach Usbekistan 7–14 Tage (Vorbestellung).", "price": "122", "origin": "EU → UZ", "cat": "parfum", "currency": "EUR", "stock": "preorder", "images": [{"url": "/market-seed/sauvage.jpg", "name": "sauvage.jpg", "type": "image/jpeg"}]}'::jsonb, (select coalesce(max(position),0)+1 from public.items where kind='product'), false
